function setExplore(value){auto=!value;if(value)model.dispatch('pause');$('#intro').hidden=true;updateUI(model.snapshot());}
controls.addEventListener('start',()=>{if(ready)setExplore(true);});$('#explore').onclick=()=>setExplore(auto);
function replay(){model=createFactory();for(const g of products.values()){scene.remove(g);for(const l of g.userData.labels)if(l.name.endsWith('_identification')){l.material.map.dispose();l.material.dispose();l.geometry.dispose();}}products.clear();for(const c of cartons.values())scene.remove(c);cartons.clear();evidence.clear();$('#evidenceSelect').innerHTML='<option>No inspections yet</option>';$('#inspectionImage').hidden=true;$('#inspectionCaption').textContent='';eventCursor=0;uiStage='';selected=null;marker.visible=false;}
$('#play').onclick=()=>{if(model.snapshot().mode==='COMPLETE')replay();if(model.snapshot().mode==='RUNNING')model.dispatch('pause');else{justStarted=true;auto=true;model.dispatch('start');}$('#intro').hidden=true;updateUI(model.snapshot());};$('#estop').onclick=()=>{model.dispatch('estop');updateUI(model.snapshot());};$('#release').onclick=()=>{model.dispatch('releaseEstop');updateUI(model.snapshot());};$('#reset').onclick=()=>{model.dispatch('reset');updateUI(model.snapshot());};$('#sensorFault').onchange=e=>model.dispatch('rejectSensorFault',e.target.checked);$('#evidenceSelect').onchange=showEvidence;$('#engineering').ontoggle=()=>updateUI(model.snapshot());
$('#share').onclick=()=>{const enabled=Boolean(tracker?.enabled);$('#forwardNameLabel').hidden=!enabled;$('#forwardEmailLabel').hidden=!enabled;$('#shareNote').textContent=enabled?'Create a separate recipient link to record a share path. The recipient identifies themselves; delivery is not verified.':'This public preview is untracked. Copying it does not identify a recipient or record forwarding.';const u=new URL(location.href);u.searchParams.delete('test');u.searchParams.delete('p');$('#shareLink').value=u.href;$('#copyStatus').textContent='';$('#shareDialog').showModal();};
$('#copyLink').onclick=async()=>{let link;if(tracker?.enabled){const r=await tracker.share({intendedName:$('#forwardName').value,intendedEmail:$('#forwardEmail').value});if(!r.shareURL){$('#copyStatus').textContent='The share link was not created. Nothing was recorded as delivered.';return;}link=r.shareURL;}else{const u=new URL(location.href);u.searchParams.delete('test');u.searchParams.delete('p');link=u.href;}$('#shareLink').value=link;try{await navigator.clipboard.writeText(link);$('#copyStatus').textContent=tracker?.enabled?'Recipient link copied. Delivery is not verified.':'Public preview link copied. Viewing and forwarding are not recorded.';}catch{$('#shareLink').select();$('#copyStatus').textContent='Select and copy the link above. Nothing has been sent.';}};
const ray=new T.Raycaster(),mouse=new T.Vector2();let pointerDown=null;canvas.addEventListener('pointerdown',e=>pointerDown=[e.clientX,e.clientY]);canvas.addEventListener('pointerup',e=>{if(!ready||!$('#engineering').open||!pointerDown||Math.hypot(e.clientX-pointerDown[0],e.clientY-pointerDown[1])>6)return;const b=canvas.getBoundingClientRect();mouse.set((e.clientX-b.left)/b.width*2-1,-(e.clientY-b.top)/b.height*2+1);ray.setFromCamera(mouse,camera);const hit=ray.intersectObjects([...staticOriginal,...Object.values(actorGroups).flatMap(g=>meshList(g)),...products.values()],true)[0];if(hit)$('#picked').textContent=(hit.object.userData.name??hit.object.name)+' / INFERRED original concept geometry';});
async function boot(){try{const [base,fm,cfg]=await Promise.all([getJSON('base-manifest.json'),getJSON('factory-geometry.json'),getJSON('config.json')]);factoryMeta=fm;config=cfg;const contextInfo=await getJSON('scene-assets.json');totalBytes=base.assets.common.bytes+base.assets['pack-check'].bytes+contextInfo.context.bytes+contextInfo.carton.bytes;const loaded=await Promise.all([loadGLB(base.assets.common),loadGLB(base.assets['pack-check']),loadGLB(contextInfo.context),loadGLB(contextInfo.carton)]);[common,prototype,,cartonPrototype]=loaded;root.add(common,loaded[2]);root.updateMatrixWorld(true);factoryBounds=new T.Box3().setFromObject(root);bindCommon();bindFactory(loaded[2]);root.updateMatrixWorld(true);mergeReadonly();apply(model.snapshot());ready=true;document.body.classList.add('modelReady');overview();camera.position.copy(cameraPosition);controls.target.copy(cameraTarget);controls.update();$('#loading').hidden=true;$('#intro').hidden=false;$('#play').disabled=false;$('#play').textContent='Start process';$('#explore').disabled=false;$('#share').disabled=false;if(config.apiBase)tracker=await initializeEngagement({apiBase:config.apiBase,onStatus:v=>{$('#trackingStatus').textContent=v.message;},getStage:()=>model.snapshot().stage});else if(new URL(location.href).searchParams.has('p'))$('#trackingStatus').textContent='Tracking not activated; this visit is not recorded';}catch(error){$('#loadText').textContent='The 3D line could not load. '+error.message;$('#progress').hidden=true;console.error(error);}}
let last=performance.now();function loop(now){requestAnimationFrame(loop);const wallDt=Math.max(0,(now-last)/1000),dt=Math.min(.05,wallDt);last=now;if(ready){frameTimes.push(dt);if(frameTimes.length>180)frameTimes.shift();lastS=model.advance(dt*2);apply(lastS);director(lastS,Math.min(.2,wallDt));updateUI(lastS);controls.update();focusLabel(lastS);}renderer.render(scene,camera);}requestAnimationFrame(loop);
if(new URLSearchParams(location.search).get('test')==='1')window.factoryProof={get ready(){return ready;},get model(){return model;},snapshot:()=>model.snapshot(),advance:t=>{const s=model.advance(t);apply(s);updateUI(s);return s;},dispatch:(a,v)=>{const s=model.dispatch(a,v);apply(s);updateUI(s);return s;},get scene(){return scene;},get camera(){return camera;},get products(){return products;},get cartons(){return cartons;},get actors(){return actorGroups;},get commonActors(){return commonMechanisms;},get evidence(){return evidence;},get metadata(){return factoryMeta;},get renderer(){return renderer;},get staticBatches(){return mergedStatic;},get frameTimes(){return frameTimes;},get desiredCameraPosition(){return cameraPosition;},setGuidedStage:()=>{justStarted=true;auto=true;},replay};
boot();
